config { type: "incremental", uniqueKey: ["id"] }
SELECT id, customer_id, ts, v FROM ${ref("events")}
WHERE ts >= TIMESTAMP '2024-01-01 02:00:00'

config { type: "incremental", uniqueKey: ["id"] }
SELECT id, customer_id, ts, status, amount FROM ${ref("orders")}
WHERE status != 'cancelled'

config { type: "incremental", uniqueKey: ["order_id"] }
SELECT order_id, COUNT(*) AS line_count, SUM(qty) AS units, MAX(ts) AS last_ts
FROM ${ref("order_lines")}
${when(incremental(), "WHERE 1 = 1")}
GROUP BY order_id

config { type: "incremental", uniqueKey: ["customer_id"] }
SELECT customer_id, COUNT(*) AS order_count, MIN(ts) AS first_order_ts
FROM ${ref("orders")}
GROUP BY customer_id
HAVING COUNT(*) = 1

config { type: "incremental", uniqueKey: ["id"] }
SELECT id, customer_id, ts, v FROM ${ref("events")}
WHERE TRUE
QUALIFY ROW_NUMBER() OVER (PARTITION BY id ORDER BY ts DESC, v DESC, customer_id DESC) = 1

config { type: "incremental", uniqueKey: ["id"] }
SELECT id, customer_id, ts, amount FROM ${ref("orders")}
WHERE customer_id IN (SELECT id FROM ${ref("customers")})

config { type: "incremental", uniqueKey: ["id"] }
SELECT id, customer_id, ts, amount FROM ${ref("orders")}
ORDER BY amount DESC, id
LIMIT 3

config { type: "incremental", uniqueKey: ["channel", "order_id"] }
post_operations {
  GRANT `roles/bigquery.dataViewer` ON TABLE ${self()} TO "group:analysts@example.com"
}
SELECT 'web' AS channel, id AS order_id, ts, amount FROM ${ref("web_orders")}
UNION ALL
SELECT 'store' AS channel, id AS order_id, ts, amount FROM ${ref("store_orders")}

config { type: "incremental", uniqueKey: ["id"] }
SELECT c.id, c.name, c.signup_date
FROM ${ref("customers")} c
WHERE NOT EXISTS (SELECT 1 FROM ${ref("orders")} o WHERE o.customer_id = c.id)
post_operations {
  GRANT `roles/bigquery.dataViewer` ON TABLE ${self()} TO "group:analysts@example.com"
}

config { type: "incremental" }
pre_operations {
  DECLARE wm DEFAULT (
    ${when(incremental(), `SELECT MAX(ts) FROM ${self()}`, `SELECT TIMESTAMP '1970-01-01'`)}
  )
}
SELECT id, customer_id, ts, v FROM ${ref("events")}
WHERE ts > wm

config { type: "incremental" }
pre_operations {
  DECLARE wm DEFAULT (
    ${when(incremental(), `SELECT COALESCE(MAX(ts), TIMESTAMP '1970-01-01') FROM ${self()}`, `SELECT TIMESTAMP '1970-01-01'`)}
  )
}
SELECT id, customer_id, ts, v FROM ${ref("events")}
WHERE ts > wm

